#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    int height;
    int weight;
    int idx;
} Student;

int cmp(const void* a, const void* b) {
    Student* A = (Student*) a;
    Student* B = (Student*) b;

    return A->height != B->height ? A->height - B->height : A->weight != B->weight ? A->weight - B->weight : A->idx - B->idx;
}

int main() {
    int n;
    scanf("%d", &n);

    Student students[n];

    for(int i=0; i<n; i++) {
        scanf("%d", &students[i].height);
    }

    for(int i=0; i<n; i++) {
        scanf("%d", &students[i].weight);
        students[i].idx = i + 1;
    }


    qsort(students, n, sizeof(Student), cmp);

    char res[100000];

    for(int i=0; i<n; i++) {
        char tmp[1000];
        sprintf(tmp, "%d", students[i].idx);

        strcat(res, tmp);

        if(i < n - 1) {
            strcat(res, " ");
        }
    }

    puts(res);

    return 0;
}
